alter table public.webhook_deliveries drop constraint if exists webhook_deliveries_status_check;
alter table public.webhook_deliveries add constraint webhook_deliveries_status_check check (status in ('queued','processing','delivered','failed','dead'));
alter table public.webhook_deliveries add column if not exists lease_token uuid, add column if not exists lease_expires_at timestamptz, add column if not exists updated_at timestamptz not null default now();
create index if not exists webhook_deliveries_processing_lease_idx on public.webhook_deliveries(lease_expires_at) where status='processing';
create or replace function public.claim_customer_webhook_delivery(p_delivery_id uuid) returns setof public.webhook_deliveries language plpgsql security invoker set search_path=public as $$ begin update public.webhook_deliveries set status='dead',lease_token=null,lease_expires_at=null,last_error=coalesce(last_error,'Delivery lease expired after final attempt.'),updated_at=now() where id=p_delivery_id and status='processing' and lease_expires_at<=now() and attempt_count>=8; return query update public.webhook_deliveries d set status='processing',attempt_count=d.attempt_count+1,lease_token=gen_random_uuid(),lease_expires_at=now()+interval '2 minutes',updated_at=now() where d.id=p_delivery_id and d.attempt_count<8 and ((d.status in ('queued','failed') and d.next_attempt_at<=now()) or (d.status='processing' and d.lease_expires_at<=now())) returning d.*; end; $$;
revoke all on function public.claim_customer_webhook_delivery(uuid) from public,anon,authenticated;
grant execute on function public.claim_customer_webhook_delivery(uuid) to service_role;